// Raw counts from: perf stat -e cycles,instructions,cache-misses,LLC-load-misses
const cycles = 8_400_000_000;
const instructions = 3_360_000_000;
const cacheMisses = 900_000_000;
const llcLoadMisses = 700_000_000;

const ipc = instructions / cycles;
const l3OfMisses = llcLoadMisses / cacheMisses;

let verdict;
if (ipc < 1 && l3OfMisses > 0.5) verdict = 'memory-bound';
else if (ipc >= 2) verdict = 'compute-bound';
else verdict = 'ambiguous';

console.log('IPC=' + ipc.toFixed(2) + ' L3ofMisses=' + (l3OfMisses * 100).toFixed(0) + '% verdict=' + verdict);

